export function harthmereGeneratedInventoryIconUrl(
  itemId: string | undefined
): string | undefined {
  if (!itemId) return undefined;
  const normalized = itemId.replace(/^b:/, "");
  return (
    HARTHMERE_GENERATED_INVENTORY_ICON_URLS[
      itemId as keyof typeof HARTHMERE_GENERATED_INVENTORY_ICON_URLS
    ] ??
    HARTHMERE_GENERATED_INVENTORY_ICON_URLS[
      normalized as keyof typeof HARTHMERE_GENERATED_INVENTORY_ICON_URLS
    ]
  );
}
